// packages/react/src/components/TimePicker/__tests__/TimePicker.readOnly.test.js
import React from 'react';
import { render } from '@testing-library/react';
import { TimePicker, TimePickerSelect, SelectItem } from 'carbon-components-react';

describe('TimePicker readOnly prop', () => {
  it('applies the read-only class to the container', () => {
    const { container } = render(
      <TimePicker id="rb1" labelText="Time" readOnly>
        <TimePickerSelect id="rb1-select1" readOnly labelText="Meridiem" defaultValue="AM">
          <SelectItem value="AM" text="AM" />
        </TimePickerSelect>
        <TimePickerSelect id="rb1-select2" readOnly labelText="Zone" defaultValue="PST">
          <SelectItem value="PST" text="PST" />
        </TimePickerSelect>
      </TimePicker>
    );
    const picker = container.querySelector('.bx--time-picker');
    expect(picker).toHaveClass('bx--time-picker--readonly');
  });
});
